"""Movement, the player's body, weapon handling, bullet and blade impacts, gore."""
from parts import *

def step(sd, weight=1.0):
    seed(sd)
    heel = thud(rng.uniform(85, 110), 0.09, 0.55, 0.022, knock=0.9)
    scuff = bp(noise(0.07), rng.uniform(900, 1500), rng.uniform(3200, 4800)) * perc(0.07, 0.018, 0.004)
    grit = hp(dust(0.08, 900, 0.0006), 2500) * perc(0.08, 0.025, 0.006)
    toe = rumble(0.03, 700) * perc(0.03, 0.008, 0.001)
    return lay((nrm(heel), 0, weight), (nrm(scuff), 0.004, 0.34), (grit, 0.008, 0.16), (nrm(toe), rng.uniform(0.028, 0.04), 0.3))

